<?php
namespace App\Livewire;
use App\Models\SchoolSetting;use Illuminate\Support\Facades\Auth;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class ReportSettings extends Component {public string $stage='',$passMark='50',$bestSubjects='8',$showPosition='enabled',$showFees='enabled',$showAttendance='enabled',$showPromotion='disabled',$footer='';public function mount():void{$this->stage=\App\Services\SchoolAcademicSetup::stagesFor(Auth::user()->school)[0];$this->loadStage();}public function updatedStage():void{$this->loadStage();}private function loadStage():void{$v=SchoolSetting::where('school_id',Auth::user()->school_id)->pluck('value','key');$p="report_{$this->stage}_";$d=\App\Services\SchoolAcademicSetup::defaultReportSettings($this->stage);$this->passMark=$v[$p.'pass_mark']??(string)$d['pass_mark'];$this->bestSubjects=$v[$p.'best_subjects']??(string)$d['best_subjects'];$this->showPosition=$v[$p.'show_position']??$d['show_position'];$this->showFees=$v[$p.'show_fees']??$d['show_fees'];$this->showAttendance=$v[$p.'show_attendance']??$d['show_attendance'];$this->showPromotion=$v[$p.'show_promotion']??$d['show_promotion'];$this->footer=$v[$p.'footer']??$d['footer'];}public function save():void{$this->validate(['stage'=>'required|in:primary,lower_secondary,advanced_level,kindergarten','passMark'=>'required|numeric|min:0|max:100','bestSubjects'=>'required|integer|min:1|max:20','footer'=>'nullable|string|max:1000']);$p="report_{$this->stage}_";foreach(['pass_mark'=>$this->passMark,'best_subjects'=>$this->bestSubjects,'show_position'=>$this->showPosition,'show_fees'=>$this->showFees,'show_attendance'=>$this->showAttendance,'show_promotion'=>$this->showPromotion,'footer'=>$this->footer]as$key=>$value)SchoolSetting::updateOrCreate(['school_id'=>Auth::user()->school_id,'key'=>$p.$key],['value'=>$value]);session()->flash('status','Report settings saved for '.str($this->stage)->replace('_',' ')->title().'.');}public function render(){return view('livewire.report-settings',['stages'=>\App\Services\SchoolAcademicSetup::stagesFor(Auth::user()->school),'pageTitle'=>'Report Settings']);}}
